package blockbranch.client.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.client.gui.screens.TitleScreen;import blockbranch.realistic.*;
/** Actual native structures and connected player; no terrain excavation or model replacement. */
public final class SnowShelterView {
 private static final boolean FRONT=Boolean.getBoolean("blockbranch.snowShelterFront");private static boolean opened,saving;private static volatile boolean posed;private static volatile int view=FRONT?4:0;private static int settled;private static long began;private static volatile List<BlockPos> anchors=List.of();private static final List<Object> records=new ArrayList<>();private static SnowShelters.Plan target;
 public static void register(){
  ServerTickEvents.END_SERVER_TICK.register(server->{if(server.isDedicatedServer()||posed||server.getPlayerList().getPlayers().isEmpty())return;try{
   var player=server.getPlayerList().getPlayers().getFirst();var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var random=level.getChunkSource().randomState();int x=322872,z=-1236360;if(view==3){x=326888;z=-1183288;}if(view==4){x=432552;z=-358040;}target=g.snowShelters(random).forStart(x>>4,z>>4).orElseThrow();var chunk=level.getChunk(x>>4,z>>4);var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(net.minecraft.world.level.levelgen.structure.BuiltinStructures.IGLOO);var start=level.structureManager().getStartForStructure(holder.value(),chunk);var top=start.getPieces().stream().filter(p->((SnowShelterAccess)p).blockbranch$shelterTop()).findFirst().orElseThrow();var access=(SnowShelterAccess)top;
   var commands=server.getCommands();var source=server.createCommandSourceStack();commands.performPrefixedCommand(source,"time set 6000");commands.performPrefixedCommand(source,"weather clear");commands.performPrefixedCommand(source,"gamemode creative "+player.getName().getString());
   if(view==0||view==3||view==4){var outside=access.blockbranch$local(3,0,-1);double ax=outside.getX()+.5,az=outside.getZ()+.5,floor=Double.NaN;for(int y=target.y()+2;y>=target.y()-4;y--){var p=new BlockPos(outside.getX(),y,outside.getZ());var shape=level.getBlockState(p).getCollisionShape(level,p);if(!shape.isEmpty()){floor=y+shape.max(Direction.Axis.Y);break;}}if(!Double.isFinite(floor))throw new AssertionError("Supported snowy approach");player.setPos(ax,floor,az);player.getAbilities().flying=false;player.onUpdateAbilities();var inside=access.blockbranch$local(3,0,3);double dx=inside.getX()-outside.getX(),dz=inside.getZ()-outside.getZ(),len=Math.hypot(dx,dz);for(int step=0;step<24;step++)player.move(net.minecraft.world.entity.MoverType.SELF,new net.minecraft.world.phys.Vec3(dx/len*.25,-.08,dz/len*.25));if(Math.hypot(player.getX()-ax,player.getZ()-az)<3.5||player.getY()<target.y()+.9)throw new AssertionError("Native collision walks snowy porch: "+player.position());
    for(var at:List.of(access.blockbranch$local(1,1,3),access.blockbranch$local(1,1,5))){player.setPos(at.getX()+1.5,at.getY(),at.getZ()+.5);player.gameMode.useItemOn(player,level,player.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(at),Direction.UP,at,false));if(player.containerMenu==player.inventoryMenu)throw new AssertionError("Native furnace/workbench opens");player.closeContainer();}
   }player.getAbilities().flying=true;player.onUpdateAbilities();BlockPos camera,aim;
   if(view==1){camera=access.blockbranch$local(3,1,3);aim=access.blockbranch$local(3,1,6);}else if(view==2){var bottom=start.getPieces().stream().min(java.util.Comparator.comparingInt(p->p.getBoundingBox().minY())).orElseThrow();var lab=(SnowShelterAccess)bottom;camera=lab.blockbranch$local(3,1,7);aim=lab.blockbranch$local(3,2,2);}else{camera=FRONT?access.blockbranch$local(3,4,-12):access.blockbranch$local(-10,6,-11);aim=access.blockbranch$local(3,2,4);}
   double cx=camera.getX()+.5,cy=camera.getY(),cz=camera.getZ()+.5,dx=aim.getX()+.5-cx,dz=aim.getZ()+.5-cz,dy=aim.getY()+.5-(cy+player.getEyeHeight());double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz)));commands.performPrefixedCommand(source,"tp "+player.getName().getString()+" "+cx+" "+cy+" "+cz+" "+yaw+" "+pitch);
   var ground=new ArrayList<BlockPos>();for(int oz=-2;oz<=2;oz++)for(int ox=-2;ox<=2;ox++){int wx=(target.x()>>4)*16+ox*16+8,wz=(target.z()>>4)*16+oz*16+8;ground.add(new BlockPos(wx,g.getBaseHeight(wx,wz,net.minecraft.world.level.levelgen.Heightmap.Types.WORLD_SURFACE_WG,level,random),wz));}anchors=List.copyOf(ground);records.add(Map.of("view",view,"target",target,"camera",camera.toShortString(),"biome",level.getBiome(target.center()).unwrapKey().orElseThrow().identifier().toString(),"nativePieces",start.getPieces().size()));blockbranch.Blockbranch.LOGGER.info("SNOW_VIEW_POSED {} {}",view,target);posed=true;
  }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("SNOW_VIEW_FAIL",e);try{Files.writeString(Path.of(System.getProperty("blockbranch.snowShelterViewResult")),"FAIL "+e);}catch(Exception ignored){}server.halt(false);}});
  ClientTickEvents.END_CLIENT_TICK.register(client->{try{
   if(opened&&System.nanoTime()-began>600_000_000_000L){Files.writeString(client.gameDirectory.toPath().resolve("result.txt"),"FAIL native shelter view timeout");client.stop();return;}if(!opened&&client.gui.screen() instanceof TitleScreen){opened=true;began=System.nanoTime();client.createWorldOpenFlows().openWorld("SnowShelterReview",()->client.gui.setScreen(new TitleScreen()));return;}if(Files.exists(client.gameDirectory.toPath().resolve("result.txt"))){client.stop();return;}if(!posed||client.level==null||client.player==null||saving)return;client.options.fov().set(view==1?80:view==2?75:50);if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.gui.toastManager().clear();var area=client.levelRenderer.viewArea();if(area==null)return;int count=0;for(var at:anchors){boolean visible=false;for(int dy:new int[]{-16,0,16}){var section=area.getRenderSectionAt(at.offset(0,dy,0));visible|=section!=null&&section.getSectionMesh().hasRenderableLayers();}if(visible)count++;}if(count<20){settled=0;return;}if(++settled<100)return;saving=true;
   String name=FRONT?"snow-shelter-entrance.png":new String[]{"snow-shelter-exterior.png","snow-shelter-interior.png","snow-shelter-laboratory.png","snow-shelter-alternate.png","snow-shelter-high-taiga.png"}[view];net.minecraft.client.Screenshot.grab(client.gameDirectory,name,client.gameRenderer.mainRenderTarget(),1,message->client.execute(()->{try{if(!FRONT&&view<4){view++;settled=0;saving=false;posed=false;}else{Files.writeString(client.gameDirectory.toPath().resolve("views.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(records));Files.writeString(client.gameDirectory.toPath().resolve("result.txt"),FRONT?"PASS actual native high-snow entrance walk and straight-on view":"PASS actual native shelter views, original laboratory, both palettes, walked entries and native furnace/workbench interactions");client.stop();}}catch(Exception e){throw new RuntimeException(e);}}));
  }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("SNOW_VIEW_CLIENT_FAIL",e);client.stop();}});
 }
}
